import assert from "node:assert/strict";
import fs from "node:fs/promises";
import path from "node:path";
import { chromium } from "playwright";

const baseUrl =
  process.env.R20_MEDIA_URL ||
  "http://127.0.0.1:4173";

const VIDEO_B64 =
  "";

const AUDIO_B64 =
  "";

const PPTX_B64 =
  "";

const out =
  path.resolve(
    "r20-media-smoke",
  );

await fs.mkdir(
  out,
  {
    recursive:
      true,
  },
);

const browser =
  await chromium.launch({
    headless:
      true,
  });

async function openClassMode(
  page,
) {
  const classMode =
    page.getByText(
      /وضع الحصة|class mode/i,
    ).first();

  assert.ok(
    await classMode.count(),
    "Class Mode entry missing",
  );

  await classMode.click();

  await page.waitForTimeout(
    450,
  );
}

async function clickMode(
  page,
  regex,
  label,
) {
  const entry =
    page.getByText(
      regex,
    ).first();

  assert.ok(
    await entry.count(),
    `${label} entry missing`,
  );

  await entry.click();

  await page.waitForTimeout(
    300,
  );
}

async function uploadByAccept(
  page,
  selector,
  file,
) {
  const input =
    page.locator(
      selector,
    ).first();

  assert.ok(
    await input.count(),
    `File input missing: ${selector}`,
  );

  await input.setInputFiles(
    file,
  );
}

async function testVideo(
  page,
) {
  await clickMode(
    page,
    /^فيديو$|video/i,
    "Video",
  );

  await uploadByAccept(
    page,
    'input[type="file"][accept*="video"]',
    {
      name:
        "r20-video-smoke.webm",
      mimeType:
        "video/webm",
      buffer:
        Buffer.from(
          VIDEO_B64,
          "base64",
        ),
    },
  );

  await page.waitForTimeout(
    700,
  );

  const surface =
    page.locator(
      '[data-r20-media-surface="video"]',
    ).first();

  const video =
    surface.locator(
      '[data-r20-media-target="video"]',
    ).first();

  assert.equal(
    await surface.isVisible(),
    true,
    "Video surface hidden",
  );

  assert.equal(
    await video.isVisible(),
    true,
    "Video element hidden",
  );

  const fit =
    await video.evaluate(
      (node) =>
        getComputedStyle(
          node,
        ).objectFit,
    );

  assert.equal(
    fit,
    "contain",
  );

  const controls =
    surface.locator(
      '[data-r20-media-controls="video"]',
    ).first();

  assert.equal(
    await controls.isVisible(),
    true,
    "Unified Video controls hidden",
  );

  const play =
    controls.locator(
      '[data-r20-media-action="play"]',
    ).first();

  await play.click();

  await page.waitForTimeout(
    450,
  );

  const advanced =
    await video.evaluate(
      (node) =>
        node.currentTime,
    );

  assert.ok(
    advanced > 0.05,
    `Video did not play: ${advanced}`,
  );

  const mute =
    controls.locator(
      '[data-r20-media-action="mute"]',
    ).first();

  await mute.click();

  assert.equal(
    await video.evaluate(
      (node) =>
        node.muted,
    ),
    true,
    "Video mute failed",
  );

  const seek =
    controls.locator(
      '[data-r20-media-action="seek"]',
    ).first();

  await seek.evaluate(
    (node) => {
      node.value = "700";
      node.dispatchEvent(
        new Event(
          "input",
          {
            bubbles: true,
          },
        ),
      );
    },
  );

  const seeked =
    await video.evaluate(
      (node) =>
        node.currentTime,
    );

  assert.ok(
    seeked > 0.7,
    `Video seek failed: ${seeked}`,
  );
}

async function testAudio(
  page,
) {
  await page.reload({
    waitUntil:
      "networkidle",
  });

  await openClassMode(
    page,
  );

  await clickMode(
    page,
    /^صوت$|audio/i,
    "Audio",
  );

  await uploadByAccept(
    page,
    'input[type="file"][accept*="audio"]',
    {
      name:
        "r20-audio-smoke.mp3",
      mimeType:
        "audio/mpeg",
      buffer:
        Buffer.from(
          AUDIO_B64,
          "base64",
        ),
    },
  );

  await page.waitForTimeout(
    650,
  );

  const surface =
    page.locator(
      '[data-r20-media-surface="audio"]',
    ).first();

  const audio =
    surface.locator(
      '[data-r20-media-target="audio"]',
    ).first();

  assert.equal(
    await surface.isVisible(),
    true,
    "Audio surface hidden",
  );

  const controls =
    surface.locator(
      '[data-r20-media-controls="audio"]',
    ).first();

  assert.equal(
    await controls.isVisible(),
    true,
    "Unified Audio controls hidden",
  );

  await controls.locator(
    '[data-r20-media-action="play"]',
  ).first().click();

  await page.waitForTimeout(
    350,
  );

  const advanced =
    await audio.evaluate(
      (node) =>
        node.currentTime,
    );

  assert.ok(
    advanced > 0.05,
    `Audio did not play: ${advanced}`,
  );

  const volume =
    controls.locator(
      '[data-r20-media-action="volume"]',
    ).first();

  await volume.evaluate(
    (node) => {
      node.value = "0.35";
      node.dispatchEvent(
        new Event(
          "input",
          {
            bubbles: true,
          },
        ),
      );
    },
  );

  const actualVolume =
    await audio.evaluate(
      (node) =>
        node.volume,
    );

  assert.ok(
    actualVolume >= 0.30 &&
    actualVolume <= 0.40,
    `Audio volume failed: ${actualVolume}`,
  );
}

async function testPowerPoint(
  page,
) {
  await page.reload({
    waitUntil:
      "networkidle",
  });

  await openClassMode(
    page,
  );

  await clickMode(
    page,
    /powerpoint|power point|pptx?|بوربوينت|باوربوينت/i,
    "PowerPoint",
  );

  const input =
    page.locator(
      'input[type="file"][accept*=".ppt"], input[type="file"][accept*="presentation"], input[type="file"][accept*="powerpoint"]',
    ).first();

  assert.ok(
    await input.count(),
    "PowerPoint file input missing",
  );

  await input.setInputFiles({
    name:
      "r20-powerpoint-smoke.pptx",
    mimeType:
      "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    buffer:
      Buffer.from(
        PPTX_B64,
        "base64",
      ),
  });

  await page.waitForTimeout(
    1300,
  );

  const root =
    page.locator(
      '[data-r20-ppt-root="true"]',
    ).first();

  assert.ok(
    await root.count(),
    "PowerPoint root missing",
  );

  assert.equal(
    await root.isVisible(),
    true,
    "PowerPoint root hidden",
  );

  assert.equal(
    await root.getAttribute(
      "data-r20-ppt-navigation-status",
    ),
    "ready",
    "PowerPoint navigation not detected",
  );

  const controls =
    root.locator(
      '[data-r20-ppt-controls="true"]',
    ).first();

  assert.equal(
    await controls.isVisible(),
    true,
    "PowerPoint unified controls hidden",
  );

  const before =
    await root.getAttribute(
      "data-r20-ppt-slide-signature",
    );

  await controls.locator(
    '[data-r20-ppt-action="next"]',
  ).first().click();

  await page.waitForTimeout(
    350,
  );

  const after =
    await root.getAttribute(
      "data-r20-ppt-slide-signature",
    );

  assert.notEqual(
    after,
    before,
    "PowerPoint next slide did not change rendered slide",
  );

  assert.equal(
    await root.getAttribute(
      "data-r20-ppt-slide-changed",
    ),
    "true",
    "PowerPoint renderer did not confirm a slide change",
  );

  await controls.locator(
    '[data-r20-ppt-action="previous"]',
  ).first().click();

  await page.waitForTimeout(
    300,
  );

  const restored =
    await root.getAttribute(
      "data-r20-ppt-slide-signature",
    );

  assert.ok(
    restored,
    "PowerPoint previous slide did not restore a slide signature",
  );
}

for (const viewport of [
  {
    name:
      "tablet-1280x800",
    width:
      1280,
    height:
      800,
  },
  {
    name:
      "tablet-1920x1080",
    width:
      1920,
    height:
      1080,
  },
]) {
  const context =
    await browser.newContext({
      viewport,
    });

  await context.addInitScript(() => {
    localStorage.setItem(
      "mobdea_mobile_auth_v2",
      JSON.stringify({
        role: "admin",
        name: "R20 Media Audit",
        expiresAt:
          Date.now() +
          60 * 60 * 1000,
      }),
    );
  });

  const page =
    await context.newPage();

  const errors =
    [];

  page.on(
    "pageerror",
    (error) =>
      errors.push(
        String(error),
      ),
  );

  await page.goto(
    baseUrl,
    {
      waitUntil:
        "networkidle",
    },
  );

  await openClassMode(
    page,
  );

  await testVideo(
    page,
  );

  await testAudio(
    page,
  );

  await testPowerPoint(
    page,
  );

  const overflow =
    await page.evaluate(
      () =>
        document.documentElement
          .scrollWidth -
        innerWidth,
    );

  assert.ok(
    overflow <= 4,
    `Media horizontal overflow=${overflow}`,
  );

  assert.deepEqual(
    errors,
    [],
    errors.join("\n"),
  );

  await page.screenshot({
    path:
      path.join(
        out,
        `${viewport.name}-media.png`,
      ),
    fullPage:
      true,
  });

  await context.close();
}

// Mobile landscape verifies responsive video/audio controls without requiring PPT slide UI.
{
  const context =
    await browser.newContext({
      viewport: {
        width:
          844,
        height:
          390,
      },
    });

  await context.addInitScript(() => {
    localStorage.setItem(
      "mobdea_mobile_auth_v2",
      JSON.stringify({
        role: "admin",
        name: "R20 Media Mobile Audit",
        expiresAt:
          Date.now() +
          60 * 60 * 1000,
      }),
    );
  });

  const page =
    await context.newPage();

  await page.goto(
    baseUrl,
    {
      waitUntil:
        "networkidle",
    },
  );

  await openClassMode(
    page,
  );

  await testVideo(
    page,
  );

  const overflow =
    await page.evaluate(
      () =>
        document.documentElement
          .scrollWidth -
        innerWidth,
    );

  assert.ok(
    overflow <= 4,
    `Mobile Video horizontal overflow=${overflow}`,
  );

  await page.screenshot({
    path:
      path.join(
        out,
        "mobile-landscape-844x390-video.png",
      ),
    fullPage:
      true,
  });

  await context.close();
}

await browser.close();
